insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM'), 0, 1, '출처_컬럼_매핑_일련번호', '출처 컬럼 매핑 일련번호.', 'SRC_COL_MPNG_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '출처_컬럼_매핑_일련번호');
