-- ---------- 예제 : 업무 설명 TB_SRC_COL_MPNG ----------
update TB_TBL set TASK_EXPLN = '출처에서 이름이 바뀐 컬럼을 사용자가 확인해 기존 모델 컬럼과 이은 기록. 비교·가져오기는 이 대응을 이름보다 먼저 써서 같은 컬럼으로 본다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '컬럼 매핑 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'SRC_COL_MPNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '매핑이 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '매핑한 출처 컬럼의 접속.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'SRC_CNTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 컬럼이 속한 테이블 매핑. 테이블 매핑을 해제하면 함께 지워진다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'SRC_TBL_MPNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '출처 컬럼의 비교용 이름 (DBMS 규칙으로 정규화). 이 이름의 출처 컬럼을 대응 모델 컬럼과 같은 것으로 본다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'CMPR_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확정할 때의 출처 컬럼 이름 (표시용).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'COL_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '대응하는 모델 컬럼. 모델 컬럼을 지우면 비어 ''모델 없음'' 으로 남는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'COL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확정할 때 기준으로 삼은 수집 반영 순서.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'RFLT_ORD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_COL_MPNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
