insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_IDNTFR'), e.LGCL_ENTT_SN, '출처 매핑 이력 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '출처 매핑 이력' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select nextval('SQ_LGCL_IDNTFR_ATRB'), i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = '출처 매핑 이력 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = '출처 매핑 이력') and i.IDNTFR_NM = '출처 매핑 이력 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);
-- ---------- 예제 : 논리 ↔ 물리 매핑 출처 매핑 이력 ----------
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ENTT_TBL_MPNG'), 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' where e.PRJ_SN = 0 and e.ENTT_NM = '출처 매핑 이력' and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN) and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = '출처 매핑 이력' join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN where mp.PRJ_SN = 0 and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN) and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
-- ---------- 예제 : 인덱스 TB_SRC_MPNG_HSTRY (V4 의 create index 그대로) ----------
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_IDX'), 0, t.TBL_SN, 'IX_SRC_MPNG_HSTRY_01', null, false, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SRC_MPNG_HSTRY_01');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SRC_MPNG_HSTRY_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'SRC_TBL_MPNG_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_IDX'), 0, t.TBL_SN, 'IX_SRC_MPNG_HSTRY_02', null, false, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SRC_MPNG_HSTRY_02');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SRC_MPNG_HSTRY_02' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SRC_MPNG_HSTRY' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
-- ---------- 예제 : 업무 설명 TB_SRC_MPNG_HSTRY ----------
update TB_TBL set TASK_EXPLN = '출처 테이블·컬럼 매핑이 언제 누구에 의해 어떻게 바뀌었는지 남긴 기록. 지우거나 고치지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '매핑 이력 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'SRC_MPNG_HSTRY_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이력이 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '매핑의 출처 접속.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'SRC_CNTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '바뀐 테이블 매핑 (해제된 뒤에도 번호로 남는다).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'SRC_TBL_MPNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '바뀐 매핑의 종류 : 테이블 또는 컬럼.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'TRGT_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확정·변경·이름 변경·해제 중 무엇이었는지.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'CHG_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '바뀌기 전 매핑 (출처·모델 객체 이름과 번호).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'CHG_BFR_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '바뀐 뒤 매핑. 해제면 비어 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'CHG_AFTR_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '매핑이 바뀐 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'CHG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_MPNG_HSTRY' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
